def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    candidates = []
    for key_fn in (lambda r, c: c - r, lambda r, c: r + c):
        keys = [(key_fn(r, c), color) for r, c, color in points]
        for period in range(1, 2 * max(h, w) + 1):
            mapping = {}
            valid = True
            for key, color in keys:
                residue = key % period
                if residue in mapping and mapping[residue] != color:
                    valid = False
                    break
                mapping[residue] = color
            if valid:
                candidates.append((period, len(set(k for k, _ in keys)), key_fn, mapping))
                break

    _, _, key_fn, mapping = min(candidates, key=lambda x: (x[0], x[1]))
    period = max(mapping) + 1
    return [[mapping[key_fn(r, c) % period] for c in range(w)] for r in range(h)]
